package com.citacloud.app.models;
import jakarta.persistence.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.UUID;
@Entity @Table(name="pagos") public class Pago { @Id @GeneratedValue private UUID id; @Column(name="empresa_id",nullable=false) private UUID empresaId; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="factura_id") private Factura factura; private LocalDate fecha; private BigDecimal monto; @Column(name="metodo_pago") private String metodoPago; private String referencia; private String observacion; private String estado="REGISTRADO";
 public UUID getId(){return id;} public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public Factura getFactura(){return factura;} public void setFactura(Factura v){factura=v;} public LocalDate getFecha(){return fecha;} public void setFecha(LocalDate v){fecha=v;} public BigDecimal getMonto(){return monto;} public void setMonto(BigDecimal v){monto=v;} public String getMetodoPago(){return metodoPago;} public void setMetodoPago(String v){metodoPago=v;} public String getReferencia(){return referencia;} public void setReferencia(String v){referencia=v;} public String getObservacion(){return observacion;} public void setObservacion(String v){observacion=v;} public String getEstado(){return estado;} public void setEstado(String v){estado=v;} }
